//! Izcal's JS bytecode format (layer L2e, tier R; JS spec 6.3; design
//! review part 1, bytecode note R0-B1 to R0-B11).
//!
//! - The opcode table is generated by `hg-opgen` from the `.hgop`
//!   operations ([`generated`], R0-O2): numbers, mnemonics, operand kinds,
//!   accumulator modes, the intrinsics and the format identifier.
//! - [`decode`] reads one instruction from a byte stream, with the
//!   `Wide2` and `Wide4` scaling prefixes (R0-B1).
//! - [`Unit`] is a function's bytecode with its counts, slot kinds and
//!   constant kinds; its image form ([`Unit::to_image`], [`UnitView`]) is
//!   a pointer-free little-endian byte string parsed as hostile input with
//!   checked arithmetic (R0-B7, G18), and [`seal`] writes it into the
//!   trusted region (JS-D16).
//! - [`assemble`] and [`disassemble`] are the text assembler of the
//!   bytecode note's Section 7.
//!
//! The verifier is JS-M1's; the tables it needs (operand kinds, constant
//! and slot kinds, intrinsic arities, terminators) are here. G13: no OS
//! access. Threading: plain data, any thread.

#![forbid(unsafe_code)]

mod asm;
mod decode;
mod disasm;
pub mod generated;
#[cfg(test)]
mod tests;
mod unit;

pub use asm::{AsmError, assemble};
pub use decode::{DecodeError, Instr, decode};
pub use disasm::disassemble;
pub use generated::opcodes::{FORMAT_ID, Intrinsic, OP_COUNT, Op};
pub use unit::{Constant, ConstantRef, ImageError, Unit, UnitKind, UnitView, Utf16, open, seal};

/// `Invalid` (0x00): zeroed or truncated memory never decodes (R0-B1).
pub const INVALID: u8 = 0x00;
/// The reserved `Extended` prefix (0xFD), for a second opcode byte.
pub const EXTENDED: u8 = 0xFD;
/// `Wide2` (0xFE): every operand of the next instruction is 2 bytes.
pub const WIDE2: u8 = 0xFE;
/// `Wide4` (0xFF): every operand of the next instruction is 4 bytes.
pub const WIDE4: u8 = 0xFF;

/// A register operand: a signed slot index relative to the frame record
/// (bytecode note 4.3). Locals are `0..registers`, the receiver is −13
/// and parameter *j* is −14 − *j*; −12 to −1 address the header and are
/// never valid operands.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Reg(pub i32);

impl Reg {
    /// The receiver, `this`.
    pub const RECEIVER: Self = Self(-13);

    /// Local register `i`.
    pub fn local(i: u32) -> Option<Self> {
        i32::try_from(i).ok().map(Self)
    }

    /// Parameter `j`.
    pub fn param(j: u32) -> Option<Self> {
        i32::try_from(j)
            .ok()
            .and_then(|j| (-14i32).checked_sub(j))
            .map(Self)
    }

    /// What the register names in a frame of `params` parameters and
    /// `registers` locals, or `None` for the header hole or out of range.
    pub fn resolve(self, params: u32, registers: u32) -> Option<RegKind> {
        let v = self.0;
        if v >= 0 {
            let i = u32::try_from(v).ok()?;
            return (i < registers).then_some(RegKind::Local(i));
        }
        if v == -13 {
            return Some(RegKind::Receiver);
        }
        if v <= -14 {
            let j = u32::try_from(-14i64 - i64::from(v)).ok()?;
            return (j < params).then_some(RegKind::Param(j));
        }
        None
    }
}

/// What a register operand names.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RegKind {
    /// A local.
    Local(u32),
    /// The receiver.
    Receiver,
    /// A parameter.
    Param(u32),
}

/// A constant's kind (bytecode note 4.5).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum ConstKind {
    /// A Number.
    Number,
    /// A String.
    String,
    /// An interned property key.
    Key,
}

impl ConstKind {
    /// The kind's assembler name.
    pub const fn name(self) -> &'static str {
        match self {
            Self::Number => "number",
            Self::String => "string",
            Self::Key => "key",
        }
    }

    /// The kind named `s`.
    pub fn parse(s: &str) -> Option<Self> {
        match s {
            "number" => Some(Self::Number),
            "string" => Some(Self::String),
            "key" => Some(Self::Key),
            _ => None,
        }
    }

    const fn bit(self) -> u8 {
        match self {
            Self::Number => 1,
            Self::String => 2,
            Self::Key => 4,
        }
    }

    /// The kind's byte in a unit image.
    pub const fn byte(self) -> u8 {
        self.bit()
    }

    /// The kind encoded as `b` in an image.
    pub const fn from_byte(b: u8) -> Option<Self> {
        match b {
            1 => Some(Self::Number),
            2 => Some(Self::String),
            4 => Some(Self::Key),
            _ => None,
        }
    }
}

/// A set of constant kinds an operand accepts.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct ConstKinds(u8);

impl ConstKinds {
    /// No kind.
    pub const NONE: Self = Self(0);
    /// Numbers.
    pub const NUMBER: Self = Self(1);
    /// Strings.
    pub const STRING: Self = Self(2);
    /// Keys.
    pub const KEY: Self = Self(4);
    /// Numbers and strings (a `LoadConst` operand).
    pub const NUMBER_STRING: Self = Self(3);

    /// Both sets.
    pub const fn union(self, other: Self) -> Self {
        Self(self.0 | other.0)
    }

    /// Whether `k` is in the set.
    pub const fn contains(self, k: ConstKind) -> bool {
        self.0 & k.bit() != 0
    }
}

/// An IC slot's kind (bytecode note 4.6).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum SlotKind {
    /// A named load.
    Load,
    /// A named store.
    Store,
    /// A keyed load.
    KeyedLoad,
    /// A keyed store.
    KeyedStore,
    /// A binary operation.
    Binary,
    /// A unary operation.
    Unary,
    /// A comparison.
    Compare,
    /// A loop back-edge counter.
    Loop,
}

impl SlotKind {
    /// Every kind, in byte order.
    pub const ALL: [Self; 8] = [
        Self::Load,
        Self::Store,
        Self::KeyedLoad,
        Self::KeyedStore,
        Self::Binary,
        Self::Unary,
        Self::Compare,
        Self::Loop,
    ];

    /// The kind's assembler name.
    pub const fn name(self) -> &'static str {
        match self {
            Self::Load => "load",
            Self::Store => "store",
            Self::KeyedLoad => "keyed-load",
            Self::KeyedStore => "keyed-store",
            Self::Binary => "binary",
            Self::Unary => "unary",
            Self::Compare => "compare",
            Self::Loop => "loop",
        }
    }

    /// The kind named `s`.
    pub fn parse(s: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|k| k.name() == s)
    }

    /// The kind's byte in a unit image.
    pub const fn byte(self) -> u8 {
        match self {
            Self::Load => 0,
            Self::Store => 1,
            Self::KeyedLoad => 2,
            Self::KeyedStore => 3,
            Self::Binary => 4,
            Self::Unary => 5,
            Self::Compare => 6,
            Self::Loop => 7,
        }
    }

    /// The kind encoded as `b`.
    pub fn from_byte(b: u8) -> Option<Self> {
        Self::ALL.into_iter().find(|k| k.byte() == b)
    }
}

/// An operand kind (bytecode note 4.2).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum OperandKind {
    /// A frame register (signed).
    Reg,
    /// A count of consecutive registers.
    Cnt,
    /// A signed immediate.
    Imm,
    /// A forward jump distance.
    Fwd,
    /// A backward jump distance.
    Back,
    /// An intrinsic id.
    Intr,
    /// A constant index, accepting these kinds.
    Const(ConstKinds),
    /// An IC slot index, of this kind.
    Slot(SlotKind),
}

impl OperandKind {
    /// Whether the operand is encoded signed.
    pub const fn signed(self) -> bool {
        matches!(self, Self::Reg | Self::Imm)
    }
}

/// An opcode's accumulator mode.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AccMode {
    /// Not used.
    None,
    /// Read.
    In,
    /// Written.
    Out,
    /// Read and written.
    InOut,
}

/// An opcode's table entry.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct OpInfo {
    /// The mnemonic.
    pub mnemonic: &'static str,
    /// The operand kinds, in encoding order.
    pub operands: &'static [OperandKind],
    /// The accumulator mode.
    pub acc: AccMode,
    /// Control never continues to the next instruction (`Return`, `Jump`,
    /// `LoopBack`): a unit ends with one.
    pub terminator: bool,
    /// Some path may run user code.
    pub may_call_user: bool,
}
